		ELIF iCodRetSp = 2 THEN
			LET cCodRet = '00717';		END IF;

		IF DBINFO("sqlca.sqlerrd2") = 0 THEN
			LET cCodRet = "00017"; --NO EXISTEN REGISTROS
		END IF;

		RETURN cCodRet,cNumSolicitud,cNumCliente;
	END;	
